// energy/degradation sketch for: Additive Manufacturing Process Generator
let c = 1.0; const samples = [];
for (let i = 0; i < 625; i++) { c *= 0.99961; if (i % 100 === 0) samples.push(+c.toFixed(4)); }
console.log(JSON.stringify({ cycles: 625, retention: +c.toFixed(4), samples: samples,
  eolReached: c < 0.8 }));

